import React from 'react';
import "../styles/Spinner.css"

type SpinnerProps = {
  size?: string
}

function Spinner({size}:SpinnerProps) {
  return (<div className="spinner" style={{ 
    width: size ? `${size}px` : "100%", 
    height: size ? `${size}px` : "100%" 
  }}></div>);
}

export default Spinner;
